import{_ as s,o as n,c as a,a6 as t}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"server 与 listen","description":"listen 的三种形式与全部参数、http2 参数的废弃、reuseport 与 backlog，以及 server 级常用指令。","frontmatter":{"title":"server 与 listen","description":"listen 的三种形式与全部参数、http2 参数的废弃、reuseport 与 backlog，以及 server 级常用指令。","source":"https://daiw.org/manual/nginx/server-listen"},"headers":[],"relativePath":"manual/tools/nginx/server-listen.md","filePath":"manual/tools/nginx/server-listen.md"}'),r={name:"manual/tools/nginx/server-listen.md"};function p(l,e,i,o,d,c){return n(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="server-与-listen" tabindex="-1">server 与 listen <a class="header-anchor" href="#server-与-listen" aria-label="Permalink to &quot;server 与 listen&quot;">​</a></h1><h2 id="listen" tabindex="-1">listen <a class="header-anchor" href="#listen" aria-label="Permalink to &quot;listen&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    listen address[:port] [parameters];</span></span>
<span class="line"><span>         listen port [parameters];</span></span>
<span class="line"><span>         listen unix:path [parameters];</span></span>
<span class="line"><span>默认:    listen *:80 | *:8000;</span></span>
<span class="line"><span>上下文:  server</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>三种形式：<strong><code>地址[:端口]</code></strong>、<strong>纯端口</strong>、<strong>UNIX 套接字</strong>。</p><p>默认值那个 <code>*:80 | *:8000</code> 的写法含义是：以 root 运行时默认 80，非 root 时默认 8000（绑不了特权端口）。</p><h3 id="常见写法" tabindex="-1">常见写法 <a class="header-anchor" href="#常见写法" aria-label="Permalink to &quot;常见写法&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>listen 80;                      # 所有 IPv4 地址的 80 端口</span></span>
<span class="line"><span>listen *:8000;                  # 同上，显式通配</span></span>
<span class="line"><span>listen 127.0.0.1:8000;          # 仅本机</span></span>
<span class="line"><span>listen [::]:8000;               # IPv6</span></span>
<span class="line"><span>listen localhost:8000;</span></span>
<span class="line"><span>listen unix:/var/run/nginx.sock;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="http2-参数已废弃" tabindex="-1">http2 参数已废弃 <a class="header-anchor" href="#http2-参数已废弃" aria-label="Permalink to &quot;http2 参数已废弃&quot;">​</a></h2><p>官方文档对 <code>listen</code> 的 <code>http2</code> 参数标注：</p><blockquote><p><code>http2</code> — Configure port to accept HTTP/2 connections (<strong>deprecated</strong>; use <code>http2</code> directive instead)</p></blockquote><p><strong><code>listen 443 ssl http2;</code> 这种写法已被官方标记为废弃</strong>（1.25.1 起分离），应改成：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>listen 443 ssl;</span></span>
<span class="line"><span>http2 on;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>原因是 <code>http2</code> 作为 listen 参数是<strong>端口级</strong>的，而独立的 <code>http2</code> 指令可以写在 <code>http</code>/<code>server</code> 级，粒度更合理——同一端口上不同 server 可以有不同的 HTTP/2 开关。</p><p>旧写法目前仍能工作，但网上绝大多数教程停留在旧形式，新配置应该用新写法。</p><h2 id="全部参数" tabindex="-1">全部参数 <a class="header-anchor" href="#全部参数" aria-label="Permalink to &quot;全部参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>含义</th></tr></thead><tbody><tr><td><code>default_server</code></td><td>该 address:port 的<a href="/Front2Full/manual/tools/nginx/request-processing">默认服务器</a></td></tr><tr><td><code>ssl</code></td><td>该端口所有连接走 TLS</td></tr><tr><td><code>http2</code></td><td><strong>已废弃</strong>，改用 <code>http2</code> 指令</td></tr><tr><td><code>quic</code></td><td>接受 QUIC 连接（<strong>1.25.0+</strong>），<a href="/Front2Full/manual/tools/nginx/http2-http3">HTTP/3</a> 用</td></tr><tr><td><code>proxy_protocol</code></td><td>该端口所有连接走 PROXY 协议</td></tr><tr><td><code>backlog=number</code></td><td><code>listen()</code> 的 backlog。默认 BSD/macOS 为 -1，其他为 <strong>511</strong></td></tr><tr><td><code>reuseport</code></td><td><strong>每个 worker 独立 socket</strong>（<code>SO_REUSEPORT</code>），Linux 3.9+</td></tr><tr><td><code>bind</code></td><td>对该 address:port 单独调 <code>bind()</code></td></tr><tr><td>\`ipv6only=on</td><td>off\`</td></tr><tr><td><code>deferred</code></td><td>延迟 accept（Linux <code>TCP_DEFER_ACCEPT</code>）</td></tr><tr><td><code>fastopen=number</code></td><td>TCP Fast Open 队列长度</td></tr><tr><td><code>so_keepalive=...</code></td><td>TCP keepalive，形如 <code>30m::10</code></td></tr><tr><td><code>rcvbuf=</code> / <code>sndbuf=</code></td><td>socket 收发缓冲</td></tr><tr><td><code>accept_filter=</code></td><td>FreeBSD/NetBSD 的 <code>dataready</code> / <code>httpready</code></td></tr><tr><td><code>multipath</code></td><td>Multipath TCP，Linux 5.6+</td></tr><tr><td><code>setfib=number</code></td><td>路由表，仅 FreeBSD</td></tr></tbody></table><h3 id="reuseport" tabindex="-1">reuseport <a class="header-anchor" href="#reuseport" aria-label="Permalink to &quot;reuseport&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>listen 80 reuseport;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>每个 worker 拿到<strong>自己的监听 socket</strong>，由内核直接把新连接分发到各 worker。</p><p>价值：<strong>彻底消除惊群与 accept 争抢</strong>，高并发短连接下能显著提升吞吐与均衡性。这也是 <a href="/Front2Full/manual/tools/nginx/core-module"><code>accept_mutex</code> 默认关闭</a>的底气之一。</p><p>注意：<code>reuseport</code> <strong>只需在一个 server 块的 listen 上写一次</strong>，同 address:port 的其他 server 不要重复写（会报错）。</p><h3 id="ipv6only" tabindex="-1">ipv6only <a class="header-anchor" href="#ipv6only" aria-label="Permalink to &quot;ipv6only&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>listen [::]:80;                # 默认 ipv6only=on，只收 IPv6</span></span>
<span class="line"><span>listen [::]:80 ipv6only=off;   # 同时收 IPv4（v4-mapped）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>默认 <code>on</code></strong>。想用一个 socket 同时服务 v4/v6 才关掉，但更常见的做法是写两条 listen：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>listen 80;</span></span>
<span class="line"><span>listen [::]:80;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="backlog" tabindex="-1">backlog <a class="header-anchor" href="#backlog" aria-label="Permalink to &quot;backlog&quot;">​</a></h3><p>未被 accept 的连接排队长度，<strong>默认 511</strong>。突发流量下 accept 队列打满会导致连接被拒（表现为客户端连接超时）。高并发场景可调大，但同时要抬高内核的 <code>net.core.somaxconn</code>——<strong>两者取较小值生效</strong>。</p><h2 id="server-name" tabindex="-1">server_name <a class="header-anchor" href="#server-name" aria-label="Permalink to &quot;server\\_name&quot;">​</a></h2><p>见 <a href="/Front2Full/manual/tools/nginx/request-processing">nginx 如何处理请求</a>的四级优先级。补充几个写法：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server_name example.com www.example.com;   # 多个名字</span></span>
<span class="line"><span>server_name *.example.com;                 # 前置通配</span></span>
<span class="line"><span>server_name mail.*;                        # 后置通配</span></span>
<span class="line"><span>server_name ~^www(?&lt;num&gt;\\d+)\\.example\\.com$;  # 正则 + 命名捕获</span></span>
<span class="line"><span>server_name &quot;&quot;;                            # 匹配无 Host 的请求</span></span>
<span class="line"><span>server_name _;                             # 「无效名」惯例，见下</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong><code>server_name _;</code> 不是什么特殊语法。</strong> <code>_</code> 只是一个不可能与任何真实 Host 匹配的普通名字（下划线不是合法域名字符）。它常与 <code>default_server</code> 一起用来表达「这是兜底块」，但<strong>起作用的是 <code>default_server</code>，不是 <code>_</code></strong>。</p><p>写成 <code>server_name __;</code> 或 <code>server_name ---;</code> 效果完全一样。</p><p>正则形式的<strong>命名捕获可以直接当变量用</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server {</span></span>
<span class="line"><span>    server_name ~^(?&lt;subdomain&gt;.+)\\.example\\.com$;</span></span>
<span class="line"><span>    root /sites/$subdomain;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="client-max-body-size" tabindex="-1">client_max_body_size <a class="header-anchor" href="#client-max-body-size" aria-label="Permalink to &quot;client\\_max\\_body\\_size&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    client_max_body_size size;</span></span>
<span class="line"><span>默认:    client_max_body_size 1m;</span></span>
<span class="line"><span>上下文:  http, server, location</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>请求体大小上限，<strong>默认仅 1 MB</strong>。超过返回 <strong><code>413</code></strong>（<a href="https://daiw.org/manual/http11/status-4xx" target="_blank" rel="noreferrer">Content Too Large</a>）。</p><p>设为 <code>0</code> 关闭检查。</p><p>「上传文件失败/413」的头号原因就是这个 1m 默认值。改的时候注意：如果后面还有一层上游（另一个 nginx、应用服务器），<strong>每一层都要改</strong>——任何一层拒绝都会失败。</p><h2 id="keepalive-timeout" tabindex="-1">keepalive_timeout <a class="header-anchor" href="#keepalive-timeout" aria-label="Permalink to &quot;keepalive\\_timeout&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    keepalive_timeout timeout [header_timeout];</span></span>
<span class="line"><span>默认:    keepalive_timeout 75s;</span></span>
<span class="line"><span>上下文:  http, server, location</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li><strong>第一个参数</strong>：服务端保持<a href="https://daiw.org/manual/http11/connection-management" target="_blank" rel="noreferrer">长连接</a>的超时。设为 <code>0</code> <strong>禁用 keep-alive</strong>。</li><li><strong>第二个参数（可选）</strong>：写进响应头 <code>Keep-Alive: timeout=N</code> 的值。</li></ul><p>两者<strong>可以不同</strong>——常见做法是让通告值略小于实际值，给客户端留出关闭余量：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>keepalive_timeout 65s 60s;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="server-tokens" tabindex="-1">server_tokens <a class="header-anchor" href="#server-tokens" aria-label="Permalink to &quot;server\\_tokens&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    server_tokens on | off | build | string;</span></span>
<span class="line"><span>默认:    server_tokens on;</span></span>
<span class="line"><span>上下文:  http, server, location</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>控制错误页与 <a href="https://daiw.org/manual/http11/context-fields" target="_blank" rel="noreferrer"><code>Server</code> 响应头</a>里是否带 nginx 版本号。</p><table tabindex="0"><thead><tr><th>值</th><th>效果</th></tr></thead><tbody><tr><td><code>on</code></td><td><code>Server: nginx/1.30.6</code></td></tr><tr><td><code>off</code></td><td><code>Server: nginx</code>（<strong>版本隐藏，但仍暴露是 nginx</strong>）</td></tr><tr><td><code>build</code></td><td>版本 + 构建名（1.11.10+）</td></tr><tr><td><code>string</code></td><td>自定义（<strong>商业版</strong>，1.9.13+）；空串则完全去掉 <code>Server</code> 头</td></tr></tbody></table><p><strong>开源版做不到彻底隐藏 <code>Server</code> 头</strong>——<code>off</code> 只去掉版本号。要完全去掉需要商业版，或用第三方模块 <code>headers-more</code>。</p><p>生产建议至少：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server_tokens off;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>理由见 <a href="https://daiw.org/manual/http11/context-fields" target="_blank" rel="noreferrer">HTTP 的 <code>Server</code> 字段</a>：精确版本号方便攻击者匹配已知漏洞。</p><h2 id="一个典型-server-块" tabindex="-1">一个典型 server 块 <a class="header-anchor" href="#一个典型-server-块" aria-label="Permalink to &quot;一个典型 server 块&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server {</span></span>
<span class="line"><span>    listen              443 ssl reuseport;</span></span>
<span class="line"><span>    listen              [::]:443 ssl;</span></span>
<span class="line"><span>    http2               on;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    server_name         example.com www.example.com;</span></span>
<span class="line"><span>    root                /var/www/example;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    client_max_body_size 20m;</span></span>
<span class="line"><span>    keepalive_timeout    65s 60s;</span></span>
<span class="line"><span>    server_tokens        off;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    ssl_certificate     /etc/ssl/example.crt;</span></span>
<span class="line"><span>    ssl_certificate_key /etc/ssl/example.key;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    location / {</span></span>
<span class="line"><span>        try_files $uri $uri/ =404;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><p>下一篇：<a href="/Front2Full/manual/tools/nginx/location">location 匹配规则</a>。</p>`,55)])])}const h=s(r,[["render",p]]);export{u as __pageData,h as default};
